import path from 'node:path';

export interface LlmProviderDefaults {
  baseUrl: string;
  model: string;
  apiKey: string;
}

export interface AppConfig {
  port: number;
  host: string;
  cos: {
    bucket: string;
    region: string;
    accessKey: string;
    secretKey: string;
    indexKey: string;
