      if (isAbortError) {
        throw new Error(`${providerName} call timed out after ${timeout}ms`);
      }

      throw error instanceof Error ? error : new Error(`${providerName} call failed`);
    }
  }

  throw new Error(`${providerName} call failed`);
};

