  const instance = {
    data: JSON.parse(JSON.stringify(config.data || {})),
    setData(update) {
      if (!update || Object.keys(update).length === 0) {
        return;
      }
      Object.entries(update).forEach(([key, value]) => {
        if (!key.includes('[') && !key.includes('.')) {
          this.data[key] = value;
